<script setup lang="ts">
import {computed,reactive} from 'vue';import ImagePicker from './ImagePicker.vue';import ResilientImage from './ResilientImage.vue';import {themes,backgroundValue} from './appearance';import type {RequestFn} from './media';
const props=defineProps<{model:Record<string,any>,request:RequestFn}>();const emit=defineEmits<{busy:[value:boolean],retry:[]}>();
function ids(value:unknown){const m=String(value||'').match(/^\/portal\/v1\/media\/([a-f0-9]{32})$/);return m?[m[1]!]:[]}
const examples=computed(()=>[{key:'background_desktop',title:'电脑端背景',hint:'适合横向图片，建议 1920 × 1080'},{key:'background_mobile',title:'手机端背景',hint:'适合竖向图片，留空时沿用电脑端背景'}]);
const statuses=reactive<Record<string,string>>({}),retries=reactive<Record<string,number>>({});
const statusText:Record<string,string>={idle:'未设置背景',loading:'正在加载图片…',retrying:'暂未加载成功，正在限次重试…',ready:'图片已加载',failed:'图片加载失败：请检查图片源、网络或防盗链限制；可重试或上传图片'};
</script>
<template><section class="panel"><span class="eyebrow">APPEARANCE</span><h2>让站点拥有自己的风格</h2><p class="muted">设置全站默认主题。访客与登录用户也可以在顶部切换，仅保存在自己的浏览器中。</p><div class="theme-options"><label v-for="t in themes" :key="t.value" :class="['theme-option',t.value,{selected:(model.theme||'mint')===t.value}]"><input type="radio" v-model="model.theme" :value="t.value"><span class="theme-swatch"></span>{{t.label}}</label></div><label>背景遮罩强度 · {{model.background_dim||0}}%<input type="range" v-model.number="model.background_dim" min="0" max="85" step="5"></label><p class="muted">遮罩用于保持文字清晰，背景图不会影响表单和操作区域的可读性。</p></section><div class="appearance-grid"><section class="panel" v-for="item in examples" :key="item.key"><h3>{{item.title}}</h3><p class="muted">{{item.hint}}</p><label>HTTPS 图片地址 / url(...)<textarea v-model="model[item.key]" rows="3" placeholder="https://api.paugram.com/wallpaper/?category=anime" maxlength="2100"/></label><ImagePicker :model-value="ids(model[item.key])" scope="background" :request="request" :max="1" @update:model-value="model[item.key]=$event.length?'/portal/v1/media/'+$event[0]:''" @busy="emit('busy',$event)"/><div class="actions"><button type="button" @click="model[item.key]=''">清除背景</button></div><ResilientImage v-if="backgroundValue(model[item.key])" :key="item.key+':'+(retries[item.key]||0)" :src="backgroundValue(model[item.key])" class="background-preview" alt="背景预览" @status="statuses[item.key]=$event"/><p v-if="model[item.key]" class="background-status" :class="{failed:statuses[item.key]==='failed'}" role="status">{{backgroundValue(model[item.key])?statusText[statuses[item.key]||'loading']:'地址无效，请填写 HTTPS 图片地址'}} <button v-if="statuses[item.key]==='failed'" type="button" @click="retries[item.key]=(retries[item.key]||0)+1;emit('retry')">重新加载预览</button></p><small class="muted">支持粘贴 url('https://…') !important，保存时仅保留安全图片地址；不执行 CSS。1 MiB 仅限制上传，外链不受此限制。随机图片源可能每次刷新跳转到不同图片；本站不会轮询换图。需要稳定背景时可上传本地图片。</small></section></div></template>

<style scoped>.background-status{font-size:12px;line-height:1.8;color:var(--accent)}.background-status.failed{color:#b55549}.background-status button{font-size:11px;padding:5px 9px;margin-left:6px}</style>
